// Smoke test of the built panel: every tab and view, both languages,
// desktop and phone. Catches what backend tests cannot see, such as the
// entity list that went missing in 1.1.0.
//
// Generated by aurora@aurora-smart-home (ha-integration-dev skill)
// https://github.com/tonylofgren/aurora-smart-home
import { after, before, describe, test } from "node:test";
import assert from "node:assert/strict";
import { chromium } from "playwright";
import { startServer } from "./harness.mjs";
import { readFile } from "node:fs/promises";
import { createRequire } from "node:module";

const AXE = await readFile(createRequire(import.meta.url).resolve("axe-core/axe.min.js"), "utf8");

const VIEWPORTS = {
  desktop: { width: 1100, height: 1000 },
  phone: { width: 390, height: 844 },
};
const TABS = ["overview", "database", "backups", "files", "settings"];

let server;
let browser;

before(async () => {
  server = await startServer();
  browser = await chromium.launch({
    executablePath: process.env.CHROME_PATH || undefined,
    args: ["--no-sandbox"],
  });
});

after(async () => {
  await browser?.close();
  await server?.close();
});

async function open(lang, viewport, query = "") {
  // the phone is a touch screen: the panel's coarse-pointer sizes apply
  const context = await browser.newContext({ viewport: VIEWPORTS[viewport], locale: lang, hasTouch: viewport === "phone" });
  const page = await context.newPage();
  const errors = [];
  page.on("pageerror", (err) => errors.push(String(err)));
  page.on("console", (msg) => msg.type() === "error" && errors.push(msg.text()));
  await page.goto(`${server.url}?lang=${lang}${query}`);
  await page.waitForFunction(() => window.__ready === true);
  const panel = page.locator("storage-manager-panel");
  await panel.locator("nav.tabs button").first().waitFor();
  return { page, panel, errors, close: () => context.close() };
}

async function noOverflow(page, where) {
  // nothing may make the page wider than the screen (the tab row scrolls by itself)
  const wide = await page.evaluate(() => {
    const root = document.querySelector("storage-manager-panel").shadowRoot;
    const limit = window.innerWidth + 1;
    const out = [];
    for (const el of root.querySelectorAll("*")) {
      if (el.closest("nav.tabs, nav.jumpbar")) continue;
      const box = el.getBoundingClientRect();
      if (box.width > 0 && box.right > limit) out.push(`${el.tagName.toLowerCase()}.${el.className}`);
    }
    return out.slice(0, 5);
  });
  assert.deepEqual(wide, [], `${where}: wider than the screen`);
}

async function tab(page, panel, name) {
  await panel.locator("nav.tabs button").nth(TABS.indexOf(name)).click();
  await page.waitForTimeout(250);
}

for (const lang of ["en", "de"]) {
  for (const viewport of Object.keys(VIEWPORTS)) {
    describe(`panel ${lang} ${viewport}`, () => {
      test("every tab renders without errors", async () => {
        const { page, panel, errors, close } = await open(lang, viewport);
        try {
          for (const name of TABS) {
            await tab(page, panel, name);
            await noOverflow(page, name);
          }
          await tab(page, panel, "overview");
          assert.ok(await panel.locator(".hero").count(), "overview: disk card");
          await tab(page, panel, "files");
          assert.ok(await panel.locator(".explorer-roots button").count(), "files: folder explorer");
          await tab(page, panel, "settings");
          assert.ok(await panel.locator("button.primary").count(), "settings: save button");
          assert.deepEqual(errors, []);
        } finally {
          await close();
        }
      });

      test("database views, detail sheet and inspector", async () => {
        const { page, panel, errors, close } = await open(lang, viewport);
        try {
          await tab(page, panel, "database");
          const views = panel.locator(".segmented").first().locator("button");
          assert.equal(await views.count(), 3, "database: three views of the entity list");
          await views.nth(0).click();
          assert.ok(await panel.locator("table").count(), "top causes: table");
          await views.nth(1).click();
          await page.waitForTimeout(150);
          assert.ok(await panel.locator("svg.treemap").count(), "by integration: treemap");
          await noOverflow(page, "groups");
          await panel.locator("svg.treemap g.tm").first().click();
          await page.waitForTimeout(150);
          assert.ok(await panel.locator(".filters.facets").count(), "drill-down: filters open");
          assert.ok(await panel.locator("table tbody tr").count(), "drill-down: rows");
          await noOverflow(page, "all");

          await panel.locator("table button.linklike").first().click();
          await panel.locator(".sheet").waitFor();
          await panel.locator("details.inspector > summary").click();
          await panel.locator(".raw-row").first().waitFor();
          await page.keyboard.press("Escape");
          await page.waitForTimeout(100);
          assert.equal(await panel.locator(".sheet").count(), 0, "Escape closes the detail sheet");

          await panel.locator(".window-bar button.chip").first().click();
          await panel.locator(".card.window-result").waitFor();
          await noOverflow(page, "time window");
          assert.deepEqual(errors, []);
        } finally {
          await close();
        }
      });

      test("apply asks first and the dialog takes the focus", async () => {
        const { page, panel, errors, close } = await open(lang, viewport);
        try {
          await tab(page, panel, "database");
          await panel.locator(".segmented").first().locator("button").nth(2).click();
          await panel.locator("table select, .table select").first().selectOption("drop");
          await panel.locator(".draftbar button.primary").click();
          await panel.locator(".dialog").waitFor();
          assert.ok(await panel.locator(".dialog ul.changes li").count(), "dialog lists the changes");
          const focused = await page.evaluate(
            () => document.querySelector("storage-manager-panel").shadowRoot.activeElement?.className
          );
          assert.equal(focused, "btn", "the focus is on Cancel, not on the red button");
          const active = () =>
            page.evaluate(() => {
              const root = document.querySelector("storage-manager-panel").shadowRoot;
              return root.querySelector(".dialog")?.contains(root.activeElement) ?? false;
            });
          for (let i = 0; i < 6; i++) await page.keyboard.press("Tab");
          assert.ok(await active(), "Tab stays inside the dialog");
          for (let i = 0; i < 6; i++) await page.keyboard.press("Shift+Tab");
          assert.ok(await active(), "Shift+Tab stays inside the dialog");
          const label = await panel.locator(".dialog").getAttribute("aria-labelledby");
          assert.equal(await panel.locator(`#${label}`).count(), 1, "the dialog is named by its title");
          await page.keyboard.press("Escape");
          await page.waitForTimeout(100);
          assert.equal(await panel.locator(".dialog").count(), 0, "Escape closes the dialog");
          assert.equal(await panel.locator('.live[role="status"]').count(), 1, "the live region is always there");
          const sent = await page.evaluate(() => window.__calls.map((c) => c.type));
          assert.ok(!sent.includes("storage_manager/apply"), "nothing applied without confirmation");
          assert.deepEqual(errors, []);
        } finally {
          await close();
        }
      });

      test("a shorter global retention asks first", async () => {
        const { page, panel, errors, close } = await open(lang, viewport, "&unlocked=1");
        try {
          await tab(page, panel, "settings");
          const field = panel.locator('input[name="purge_keep_days"]');
          await field.fill("2");
          await field.dispatchEvent("change");
          await panel.locator("button.settings-save").click();
          await panel.locator(".dialog").waitFor();
          const sent = await page.evaluate(() => window.__calls.map((c) => c.type));
          assert.ok(!sent.includes("storage_manager/settings"), "not saved before the confirmation");
          await page.keyboard.press("Escape");
          assert.deepEqual(errors, []);
        } finally {
          await close();
        }
      });

      test("event types that are still recorded are marked", async () => {
        const { page, panel, errors, close } = await open(lang, viewport);
        try {
          await tab(page, panel, "database");
          assert.equal(await panel.locator("#sec-events .list-row").count(), 0, "events start folded");
          await panel.locator("nav.jumpbar button", { hasText: lang === "de" ? "Ereignisse" : "Events" }).click();
          await panel.locator("#sec-events .list-row").first().waitFor();
          assert.ok(await panel.locator("#sec-events .list-row .tag.warn").count(), "still recorded");
          assert.equal(
            await page.evaluate(() => document.querySelector("storage-manager-panel").shadowRoot.activeElement?.id),
            "sec-events",
            "the jump moves the focus to the section"
          );
          assert.deepEqual(errors, []);
        } finally {
          await close();
        }
      });

      if (viewport === "phone") {
        test("buttons are big enough for a finger", async () => {
          const { page, panel, errors, close } = await open(lang, viewport);
          try {
            for (const name of TABS) {
              await tab(page, panel, name);
              const small = await page.evaluate(() => {
                const root = document.querySelector("storage-manager-panel").shadowRoot;
                return [...root.querySelectorAll("main .btn, main .chip, main .fold-toggle, main .segmented button")]
                  .filter((el) => el.offsetParent !== null && el.getBoundingClientRect().height < 44)
                  .map((el) => `${el.className}: ${el.textContent.trim().slice(0, 30)}`)
                  .slice(0, 5);
              });
              assert.deepEqual(small, [], `${name}: targets under 44 px`);
            }
            assert.deepEqual(errors, []);
          } finally {
            await close();
          }
        });
      }

      test("a new health problem opens the folded health card again", async () => {
        const { page, panel, errors, close } = await open(lang, viewport);
        try {
          await tab(page, panel, "database");
          const toggle = panel.locator("#sec-health .fold-toggle");
          assert.equal(await toggle.getAttribute("aria-expanded"), "true", "open while a check needs a look");
          await toggle.click();
          assert.equal(await toggle.getAttribute("aria-expanded"), "false");
          await page.evaluate(() => {
            const el = document.querySelector("storage-manager-panel");
            const health = structuredClone(el._health);
            health.database.checks.find((c) => c.key === "integrity").status = "error";
            health.database.status = "error";
            el._health = health;
          });
          await page.waitForTimeout(100);
          assert.equal(await toggle.getAttribute("aria-expanded"), "true", "opens again for the new problem");
          assert.deepEqual(errors, []);
        } finally {
          await close();
        }
      });

      test("the emergency path leads step by step and asks before deleting without backup", async () => {
        const { page, panel, errors, close } = await open(lang, viewport, "&emergency=1");
        try {
          const card = panel.locator("section.emergency");
          await card.waitFor();
          assert.equal(await card.locator("ol.emergency-steps > li").count(), 3, "three steps");
          await noOverflow(page, "emergency");
          await page.addScriptTag({ content: AXE });
          const found = await page.evaluate(async () => {
            const card = document.querySelector("storage-manager-panel").shadowRoot.querySelector("section.emergency");
            const result = await window.axe.run(card, { resultTypes: ["violations"], rules: { "color-contrast": { enabled: false } } });
            return result.violations.filter((v) => v.impact === "serious" || v.impact === "critical").map((v) => v.id);
          });
          assert.deepEqual(found, [], "axe on the emergency card");
          const names = await card.locator("button").evaluateAll((els) => els.map((el) => el.getAttribute("aria-label") || el.textContent.trim()));
          assert.equal(new Set(names).size, names.length, `every button has its own name: ${names}`);
          await card.locator("button.danger").click();
          await panel.locator(".dialog").waitFor();
          const typed = await page.evaluate(() => document.querySelector("storage-manager-panel")._dialog.typed);
          assert.equal(typed, 13, "the number of items is typed in");
          const confirm = panel.locator(".dialog .actions button.primary");
          assert.ok(await confirm.isDisabled(), "nothing without typing the number");
          await panel.locator(".dialog input").fill(String(typed));
          await confirm.click();
          await page.waitForTimeout(200);
          const call = await page.evaluate(() => window.__calls.filter((c) => c.type.endsWith("/clean")).pop());
          assert.equal(call.emergency, true);
          assert.deepEqual(call.targets, ["orphans", "events"]);
          assert.equal(call.entity_ids.length, 12);
          assert.deepEqual(errors, []);
        } finally {
          await close();
        }
      });

      test("an unknown recorder schema is shown", async () => {
        const { page, panel, errors, close } = await open(lang, viewport, "&schema=1");
        try {
          await tab(page, panel, "database");
          assert.ok(await panel.locator(".banner", { hasText: "99" }).count(), "schema banner");
          assert.deepEqual(errors, []);
        } finally {
          await close();
        }
      });

      test("sections fold, and keep their state", async () => {
        const { page, panel, errors, close } = await open(lang, viewport);
        try {
          await tab(page, panel, "database");
          const toggle = panel.locator("#sec-dead .fold-toggle");
          assert.equal(await toggle.getAttribute("aria-expanded"), "false");
          await toggle.click();
          assert.equal(await toggle.getAttribute("aria-expanded"), "true");
          assert.ok(await panel.locator("#sec-dead-body").count(), "the body is there when open");
          await tab(page, panel, "overview");
          await tab(page, panel, "database");
          assert.equal(await panel.locator("#sec-dead .fold-toggle").getAttribute("aria-expanded"), "true", "remembered");
          assert.deepEqual(errors, []);
        } finally {
          await close();
        }
      });

      test("numbers lead to their list", async () => {
        const { page, panel, errors, close } = await open(lang, viewport);
        try {
          // overview: the orphans recommendation opens the list of orphans
          const list = panel.locator(".rec .act button.btn", { hasText: lang === "de" ? "Liste" : "List" });
          assert.ok(await list.count(), "a recommendation offers its list");
          await list.first().click();
          await panel.locator("#sec-entities table").waitFor();
          const orphans = panel.locator(".chip", { hasText: lang === "de" ? "Nur verwaiste" : "Orphans only" });
          assert.equal(await orphans.getAttribute("aria-pressed"), "true", "filtered to orphans");

          // the size opens all entities, without the filter of the drill-down before
          await panel.locator("button.kpi.link").first().click();
          await page.waitForTimeout(300);
          const views = panel.locator("#sec-entities .segmented button");
          assert.equal(await views.nth(2).getAttribute("aria-selected"), "true", "database size opens all entities");
          assert.equal(await orphans.getAttribute("aria-pressed"), "false", "earlier filters are cleared");

          // the folded parts come before the long entity list
          const order = await page.evaluate(() =>
            [...document.querySelector("storage-manager-panel").shadowRoot.querySelectorAll("section.card")].map((x) => x.id)
          );
          assert.equal(order[order.length - 1], "sec-entities", `entity list last: ${order}`);
          assert.deepEqual(errors, []);
        } finally {
          await close();
        }
      });

      test("treemap and time window work with the keyboard", async () => {
        const { page, panel, errors, close } = await open(lang, viewport);
        try {
          await tab(page, panel, "database");
          await panel.locator("#sec-entities .segmented button").nth(1).click();
          const area = panel.locator("svg.treemap g.tm").first();
          await area.focus();
          await page.keyboard.press("Enter");
          await page.waitForTimeout(300);
          assert.ok(await panel.locator(".filters.facets").count(), "Enter on an area opens its entities");
          assert.equal(
            await page.evaluate(() => document.querySelector("storage-manager-panel").shadowRoot.activeElement?.id),
            "sec-entities",
            "the focus stays in the list it opened"
          );

          await panel.locator(".window-bar button.chip").last().click();
          const form = panel.locator("form.window-form");
          await form.waitFor();
          await form.locator('input[name="from"]').fill("2026-11-20T08:00");
          await form.locator('input[name="to"]').fill("2026-11-21T08:00");
          await form.locator('button[type="submit"]').click();
          await panel.locator(".card.window-result").waitFor();
          const call = await page.evaluate(() => window.__calls.filter((c) => c.type.endsWith("/writers")).pop());
          assert.equal(call.end - call.start, 86400, "the range typed in is the range asked for");
          assert.deepEqual(errors, []);
        } finally {
          await close();
        }
      });

      for (const theme of ["light", "dark"]) {
        test(`no serious accessibility findings (${theme} theme)`, async () => {
          const { page, panel, errors, close } = await open(lang, viewport, `&theme=${theme}`);
          try {
            await page.addScriptTag({ content: AXE });
            for (const name of TABS) {
              await tab(page, panel, name);
              const found = await page.evaluate(async () => {
                const root = document.querySelector("storage-manager-panel");
                const result = await window.axe.run(root, { resultTypes: ["violations"] });
                return result.violations
                  .filter((v) => v.impact === "serious" || v.impact === "critical")
                  .map((v) => `${v.id} (${v.nodes.length}): ${v.nodes[0]?.target?.join(" ")}`);
              });
              assert.deepEqual(found, [], `${name}: axe`);
            }
            assert.deepEqual(errors, []);
          } finally {
            await close();
          }
        });
      }

      test("undo shows what comes back", async () => {
        const { page, panel, errors, close } = await open(lang, viewport);
        try {
          const undo = panel.locator(".history button.btn, .list-row button.btn").filter({
            hasText: lang === "de" ? "Rückgängig" : "Undo",
          });
          await undo.first().click();
          await panel.locator(".dialog").waitFor();
          assert.ok(await panel.locator(".dialog li").count(), "rows that come back are listed");
          await page.keyboard.press("Escape");
          assert.deepEqual(errors, []);
        } finally {
          await close();
        }
      });
    });
  }
}
